<?php use Namira\{PublicPresentation as P,ProtocolValidator};$fields=$artist['data'];$termLabels=array_column($specialties,'title','id');$location=array_filter([$fields['province']??'',$fields['county']??'',$fields['city']??''],fn($x)=>P::meaningful($x));$skills=array_values(array_intersect_key($termLabels,array_flip($fields['specialties']??[]))); ?>
<div class="heading"><a class="outline" href="<?= e(url('artists')) ?>">همه هنرمندان</a></div>
<section class="panel artist-intro"><?php view('artist-avatar',['artist'=>$artist]); ?><div><h1><?= e($artist['display_name']) ?></h1><?php if($location): ?><p class="muted"><?= e(implode('، ',array_unique($location))) ?></p><?php endif ?><?php if($skills): ?><p><?= e(implode('، ',$skills)) ?></p><?php endif ?><?php if(P::meaningful($fields['summary']??null)): ?><p><?= e($fields['summary']) ?></p><?php endif ?><span class="artist-work-count"><?= fa($result['count']) ?> اثر</span></div></section>
<?php if(P::meaningful($fields['biography']??null)): ?><section class="panel artist-biography"><h2>درباره هنرمند</h2><div class="prose"><?= ProtocolValidator::safeHtml($fields['biography']) ?></div></section><?php endif ?>
<?php if(P::meaningful($fields['awards']??null)): ?><section class="panel"><h2>سوابق و افتخارات</h2><p class="prose"><?= nl2br(e($fields['awards'])) ?></p></section><?php endif ?>
<?php view('artist-socials',compact('fields')); ?><?php foreach(['private_email','private_phone'] as $contact):if(P::meaningful($fields[$contact]??null)): ?><p class="artist-public-contact"><?= e($fields[$contact]) ?></p><?php endif;endforeach ?>
<div class="heading"><h2>آثار هنری</h2><span><?= fa($result['count']) ?> اثر</span></div><?php view('cards',['images'=>$result['items']]);view('public-pagination',['count'=>$result['count'],'per'=>Namira\PublicFeed::pageSize('images'),'page'=>max(1,(int)($_GET['p']??1)),'route'=>'artist','filters'=>['id'=>$artist['id']]]); ?>
